import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';
import './index.css'; // 👈 Must be present

/**
 * Registers the Workbox service worker generated by `vite-plugin-pwa`.
 *
 * Only http(s) origins are eligible: the same bundle is also loaded from
 * `file://` inside the Electron shell, where registration always fails.
 */
function registerServiceWorker() {
  if (!import.meta.env.PROD) return; // `sw.js` only exists in the build output.
  if (!('serviceWorker' in navigator)) return;
  if (!window.location.protocol.startsWith('http')) return;

  window.addEventListener('load', () => {
    void navigator.serviceWorker
      .register(`${import.meta.env.BASE_URL}sw.js`)
      .catch(() => undefined); // Offline support is a bonus, never a hard failure.
  });
}

registerServiceWorker();

ReactDOM.createRoot(document.getElementById('root')!).render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);
